import { isolator } from '@variance-authority/isolator/vite';

/**
 * The isolator's build of `isolated/`: one preview page shows every story, and
 * every module the stories reach starts each story from the values it loaded
 * with. Regenerated by `build-storybook:isolated`.
 */
const stories = 'isolated/**/*.stories.@(js|jsx)';

export default {
  stories: [`../${stories}`],
  framework: { name: '@storybook/react-vite', options: {} },
  core: { disableTelemetry: true },
  viteFinal: async (config) => ({
    ...config,
    // Storybook reads a story file's exports once for the page, and every one
    // is an object handed to Storybook, which the isolator would warn of.
    plugins: [...(config.plugins ?? []), isolator({ exclude: ['.storybook-isolated/**', stories] })],
    oxc: { ...config.oxc, jsx: { runtime: 'automatic' } },
  }),
};
